import type { App } from 'vue'
import MaxButton from './components/MaxButton.vue'

export { MaxButton }

export interface MaxComponentsUiOptions {
  PrimeVue?: any
}

const components = {
  MaxButton
}

export const install = (app: App, options: MaxComponentsUiOptions = {}) => {
  Object.entries(components).forEach(([name, component]) => {
    app.component(name, component)
  })
}

export default {
  install
}

export * from './types'
